     1→import { useState, useCallback, useEffect } from "react";
     2→import type {
     3→  ActionFunctionArgs,
     4→  HeadersFunction,
     5→  LoaderFunctionArgs,
     6→} from "react-router";
     7→import { useFetcher, useLoaderData, useNavigate, useRouteError } from "react-router";
     8→import { useAppBridge } from "@shopify/app-bridge-react";
     9→import { authenticate } from "../shopify.server";
    10→import { boundary } from "@shopify/shopify-app-react-router/server";
    11→import db from "../db.server";
    12→import { getShopSubscription } from "../billing.server";
    13→import { PLAN_LIMITS, UNLIMITED } from "../plans";
    14→import {
    15→  Page,
    16→  Layout,
    17→  Card,
    18→  BlockStack,
    19→  InlineStack,
    20→  InlineGrid,
    21→  Text,
    22→  Badge,
    23→  Button,
    24→  TextField,
    25→  Select,
    26→  Modal,
    27→  IndexTable,
    28→  useIndexResourceState,
    29→  EmptyState,
    30→  Divider,
    31→  Box,
    32→  Tooltip,
    33→  Checkbox,
    34→  Banner,
    35→} from "@shopify/polaris";
    36→import { PlusIcon, DeleteIcon, EditIcon, ViewIcon, HideIcon } from "@shopify/polaris-icons";
    37→
    38→const DAYS_OPTIONS = [
    39→  { label: "Monday", value: "Mon" },
    40→  { label: "Tuesday", value: "Tue" },
    41→  { label: "Wednesday", value: "Wed" },
    42→  { label: "Thursday", value: "Thu" },
    43→  { label: "Friday", value: "Fri" },
    44→  { label: "Saturday", value: "Sat" },
    45→  { label: "Sunday", value: "Sun" },
    46→];
    47→
    48→export const loader = async ({ request }: LoaderFunctionArgs) => {
    49→  const { session } = await authenticate.admin(request);
    50→  const shop = session.shop;
    51→
    52→  const [rules, zones, subscription] = await Promise.all([
    53→    db.deliveryRule.findMany({
    54→      where: { shop },
    55→      orderBy: { priority: "asc" },
    56→    }),
    57→    db.zipCode.findMany({
    58→      where: { shop, zone: { not: null } },
    59→      select: { zone: true },
    60→      distinct: ["zone"],
    61→    }),
    62→    getShopSubscription(shop),
    63→  ]);
    64→
    65→  return {
    66→    rules,
    67→    zones: zones.map((z) => z.zone).filter(Boolean) as string[],
    68→    subscription,
    69→  };
    70→};
    71→
    72→export const action = async ({ request }: ActionFunctionArgs) => {
    73→  const { session } = await authenticate.admin(request);
    74→  const shop = session.shop;
    75→  const formData = await request.formData();
    76→  const intent = formData.get("intent");
    77→
    78→  if (intent === "create" || intent === "update") {
    79→    const id = String(formData.get("id") || "");
    80→    const name = String(formData.get("name") || "").trim();
    81→    const zone = String(formData.get("zone") || "").trim() || null;
    82→    const zipCodes = String(formData.get("zipCodes") || "").trim() || null;
    83→    const minOrderAmount = formData.get("minOrderAmount")
    84→      ? parseFloat(String(formData.get("minOrderAmount")))
    85→      : null;
    86→    const deliveryFee = formData.get("deliveryFee")
    87→      ? parseFloat(String(formData.get("deliveryFee")))
    88→      : null;
    89→    const freeShippingAbove = formData.get("freeShippingAbove")
    90→      ? parseFloat(String(formData.get("freeShippingAbove")))
    91→      : null;
    92→    const estimatedDays =
    93→      String(formData.get("estimatedDays") || "").trim() || null;
    94→    const cutoffTime =
    95→      String(formData.get("cutoffTime") || "").trim() || null;
    96→    const daysOfWeek =
    97→      String(formData.get("daysOfWeek") || "").trim() || null;
    98→    const priority = parseInt(String(formData.get("priority") || "0"), 10);
    99→
   100→    if (!name) return { error: "Rule name is required." };
   101→
   102→    const data = {
   103→      name,
   104→      zone,
   105→      zipCodes,
   106→      minOrderAmount,
   107→      deliveryFee,
   108→      freeShippingAbove,
   109→      estimatedDays,
   110→      cutoffTime,
   111→      daysOfWeek,
   112→      priority,
   113→    };
   114→
   115→    if (intent === "update" && id) {
   116→      try {
   117→        const existing = await db.deliveryRule.findFirst({ where: { id, shop } });
   118→        if (!existing) return { error: "Rule not found." };
   119→        await db.deliveryRule.update({ where: { id }, data });
   120→        return { success: true, action: "updated" };
   121→      } catch {
   122→        return { error: "Failed to update rule." };
   123→      }
   124→    } else {
   125→      // Plan-gating: check limits before creating a new rule
   126→      const subscription = await getShopSubscription(shop);
   127→      const { maxDeliveryRules, label: planLabel } = subscription.limits;
   128→
   129→      if (maxDeliveryRules === 0) {
   130→        return {
   131→          error:
   132→            "Delivery rules are not available on the Free plan. Upgrade to Starter or Pro.",
   133→        };
   134→      }
   135→
   136→      if (maxDeliveryRules < UNLIMITED) {
   137→        const currentCount = await db.deliveryRule.count({ where: { shop } });
   138→        if (currentCount >= maxDeliveryRules) {
   139→          return {
   140→            error: `You've reached the ${maxDeliveryRules} delivery rule limit on the ${planLabel} plan. Upgrade to Pro for unlimited rules.`,
   141→          };
   142→        }
   143→      }
   144→
   145→      await db.deliveryRule.create({ data: { shop, ...data } });
   146→      return { success: true, action: "created" };
   147→    }
   148→  }
   149→
   150→  if (intent === "delete") {
   151→    const id = String(formData.get("id"));
   152→    try {
   153→      const existing = await db.deliveryRule.findFirst({ where: { id, shop } });
   154→      if (!existing) return { error: "Rule not found." };
   155→      await db.deliveryRule.delete({ where: { id } });
   156→      return { success: true, action: "deleted" };
   157→    } catch {
   158→      return { error: "Failed to delete rule." };
   159→    }
   160→  }
   161→
   162→  if (intent === "toggle") {
   163→    const id = String(formData.get("id"));
   164→    const isActive = formData.get("isActive") === "true";
   165→    try {
   166→      const existing = await db.deliveryRule.findFirst({ where: { id, shop } });
   167→      if (!existing) return { error: "Rule not found." };
   168→      await db.deliveryRule.update({
   169→        where: { id },
   170→        data: { isActive: !isActive },
   171→      });
   172→      return { success: true, action: "toggled" };
   173→    } catch {
   174→      return { error: "Failed to toggle rule." };
   175→    }
   176→  }
   177→
   178→  if (intent === "bulk-delete") {
   179→    const ids = String(formData.get("ids") || "").split(",").filter(Boolean);
   180→    if (ids.length === 0) return { error: "No rules selected." };
   181→    try {
   182→      await db.deliveryRule.deleteMany({ where: { id: { in: ids }, shop } });
   183→      return { success: true, action: "bulk-deleted" };
   184→    } catch {
   185→      return { error: "Failed to delete rules." };
   186→    }
   187→  }
   188→
   189→  if (intent === "bulk-toggle") {
   190→    const ids = String(formData.get("ids") || "").split(",").filter(Boolean);
   191→    const active = formData.get("active") === "true";
   192→    if (ids.length === 0) return { error: "No rules selected." };
   193→    try {
   194→      await db.deliveryRule.updateMany({
   195→        where: { id: { in: ids }, shop },
   196→        data: { isActive: active },
   197→      });
   198→      return { success: true, action: active ? "bulk-activated" : "bulk-deactivated" };
   199→    } catch {
   200→      return { error: "Failed to update rules." };
   201→    }
   202→  }
   203→
   204→  return null;
   205→};
   206→
   207→type Rule = {
   208→  id: string;
   209→  name: string;
   210→  zone: string | null;
   211→  zipCodes: string | null;
   212→  minOrderAmount: number | null;
   213→  deliveryFee: number | null;
   214→  freeShippingAbove: number | null;
   215→  estimatedDays: string | null;
   216→  cutoffTime: string | null;
   217→  daysOfWeek: string | null;
   218→  isActive: boolean;
   219→  priority: number;
   220→};
   221→
   222→export default function DeliveryRulesPage() {
   223→  const { rules, zones, subscription } = useLoaderData<typeof loader>();
   224→  const limits = PLAN_LIMITS[subscription.planTier];
   225→  const isFreePlan = limits.maxDeliveryRules === 0;
   226→  const hasFiniteLimit = limits.maxDeliveryRules < UNLIMITED && !isFreePlan;
   227→  const fetcher = useFetcher<typeof action>();
   228→  const shopify = useAppBridge();
   229→  const navigate = useNavigate();
   230→
   231→  const { selectedResources, allResourcesSelected, handleSelectionChange, clearSelection } =
   232→    useIndexResourceState(rules as Rule[]);
   233→
   234→  const [modalOpen, setModalOpen] = useState(false);
   235→  const [editingRule, setEditingRule] = useState<Rule | null>(null);
   236→
   237→  // Form state
   238→  const [name, setName] = useState("");
   239→  const [zone, setZone] = useState("");
   240→  const [zipCodes, setZipCodes] = useState("");
   241→  const [minOrderAmount, setMinOrderAmount] = useState("");
   242→  const [deliveryFee, setDeliveryFee] = useState("");
   243→  const [freeShippingAbove, setFreeShippingAbove] = useState("");
   244→  const [estimatedDays, setEstimatedDays] = useState("");
   245→  const [cutoffTime, setCutoffTime] = useState("");
   246→  const [selectedDays, setSelectedDays] = useState<string[]>([
   247→    "Mon",
   248→    "Tue",
   249→    "Wed",
   250→    "Thu",
   251→    "Fri",
   252→  ]);
   253→  const [priority, setPriority] = useState("0");
   254→
   255→  const actionError =
   256→    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
   257→
   258→  const resetForm = useCallback(() => {
   259→    setName("");
   260→    setZone("");
   261→    setZipCodes("");
   262→    setMinOrderAmount("");
   263→    setDeliveryFee("");
   264→    setFreeShippingAbove("");
   265→    setEstimatedDays("");
   266→    setCutoffTime("");
   267→    setSelectedDays(["Mon", "Tue", "Wed", "Thu", "Fri"]);
   268→    setPriority("0");
   269→    setEditingRule(null);
   270→  }, []);
   271→
   272→  const openCreate = useCallback(() => {
   273→    resetForm();
   274→    setModalOpen(true);
   275→  }, [resetForm]);
   276→
   277→  const openEdit = useCallback((rule: Rule) => {
   278→    setEditingRule(rule);
   279→    setName(rule.name);
   280→    setZone(rule.zone || "");
   281→    setZipCodes(rule.zipCodes || "");
   282→    setMinOrderAmount(rule.minOrderAmount != null ? String(rule.minOrderAmount) : "");
   283→    setDeliveryFee(rule.deliveryFee != null ? String(rule.deliveryFee) : "");
   284→    setFreeShippingAbove(
   285→      rule.freeShippingAbove != null ? String(rule.freeShippingAbove) : "",
   286→    );
   287→    setEstimatedDays(rule.estimatedDays || "");
   288→    setCutoffTime(rule.cutoffTime || "");
   289→    setSelectedDays(rule.daysOfWeek ? rule.daysOfWeek.split(",") : []);
   290→    setPriority(String(rule.priority));
   291→    setModalOpen(true);
   292→  }, []);
   293→
   294→  const handleSave = useCallback(() => {
   295→    const fd = new FormData();
   296→    fd.set("intent", editingRule ? "update" : "create");
   297→    if (editingRule) fd.set("id", editingRule.id);
   298→    fd.set("name", name);
   299→    fd.set("zone", zone);
   300→    fd.set("zipCodes", zipCodes);
   301→    fd.set("minOrderAmount", minOrderAmount);
   302→    fd.set("deliveryFee", deliveryFee);
   303→    fd.set("freeShippingAbove", freeShippingAbove);
   304→    fd.set("estimatedDays", estimatedDays);
   305→    fd.set("cutoffTime", cutoffTime);
   306→    fd.set("daysOfWeek", selectedDays.join(","));
   307→    fd.set("priority", priority);
   308→    fetcher.submit(fd, { method: "POST" });
   309→  }, [
   310→    editingRule,
   311→    name,
   312→    zone,
   313→    zipCodes,
   314→    minOrderAmount,
   315→    deliveryFee,
   316→    freeShippingAbove,
   317→    estimatedDays,
   318→    cutoffTime,
   319→    selectedDays,
   320→    priority,
   321→    fetcher,
   322→  ]);
   323→
   324→  const handleDelete = useCallback(
   325→    (id: string) => {
   326→      const fd = new FormData();
   327→      fd.set("intent", "delete");
   328→      fd.set("id", id);
   329→      fetcher.submit(fd, { method: "POST" });
   330→    },
   331→    [fetcher],
   332→  );
   333→
   334→  useEffect(() => {
   335→    if (fetcher.state === "idle" && fetcher.data) {
   336→      if ("success" in fetcher.data && fetcher.data.success) {
   337→        const fetcherAction =
   338→          "action" in fetcher.data ? fetcher.data.action : "";
   339→        if (fetcherAction === "created") {
   340→          shopify.toast.show("Rule created");
   341→          setModalOpen(false);
   342→          resetForm();
   343→        } else if (fetcherAction === "updated") {
   344→          shopify.toast.show("Rule updated");
   345→          setModalOpen(false);
   346→          resetForm();
   347→        } else if (fetcherAction === "deleted") {
   348→          shopify.toast.show("Rule deleted");
   349→        } else if (fetcherAction === "toggled") {
   350→          shopify.toast.show("Rule status updated");
   351→        } else if (fetcherAction === "bulk-deleted") {
   352→          shopify.toast.show("Selected rules deleted");
   353→          clearSelection();
   354→        } else if (fetcherAction === "bulk-activated") {
   355→          shopify.toast.show("Selected rules activated");
   356→          clearSelection();
   357→        } else if (fetcherAction === "bulk-deactivated") {
   358→          shopify.toast.show("Selected rules deactivated");
   359→          clearSelection();
   360→        }
   361→      }
   362→    }
   363→  }, [fetcher.state, fetcher.data, shopify, resetForm, clearSelection]);
   364→
   365→  const handleToggle = useCallback(
   366→    (id: string, isActive: boolean) => {
   367→      const fd = new FormData();
   368→      fd.set("intent", "toggle");
   369→      fd.set("id", id);
   370→      fd.set("isActive", String(isActive));
   371→      fetcher.submit(fd, { method: "POST" });
   372→    },
   373→    [fetcher],
   374→  );
   375→
   376→  const toggleDay = useCallback(
   377→    (day: string) => {
   378→      setSelectedDays((prev) =>
   379→        prev.includes(day) ? prev.filter((d) => d !== day) : [...prev, day],
   380→      );
   381→    },
   382→    [],
   383→  );
   384→
   385→  const handleBulkDelete = useCallback(() => {
   386→    const fd = new FormData();
   387→    fd.set("intent", "bulk-delete");
   388→    fd.set("ids", selectedResources.join(","));
   389→    fetcher.submit(fd, { method: "POST" });
   390→  }, [selectedResources, fetcher]);
   391→
   392→  const handleBulkToggle = useCallback(
   393→    (active: boolean) => {
   394→      const fd = new FormData();
   395→      fd.set("intent", "bulk-toggle");
   396→      fd.set("ids", selectedResources.join(","));
   397→      fd.set("active", String(active));
   398→      fetcher.submit(fd, { method: "POST" });
   399→    },
   400→    [selectedResources, fetcher],
   401→  );
   402→
   403→  const zoneOptions = [
   404→    { label: "All zones", value: "" },
   405→    ...zones.map((z) => ({ label: z, value: z })),
   406→  ];
   407→
   408→  return (
   409→    <Page
   410→      title="Delivery Rules"
   411→      subtitle="Configure delivery fees, minimums, schedules, and conditions per zone"
   412→      backAction={{ onAction: () => navigate("/app") }}
   413→      primaryAction={
   414→        isFreePlan
   415→          ? undefined
   416→          : {
   417→              content: "Add Rule",
   418→              icon: PlusIcon,
   419→              onAction: openCreate,
   420→            }
   421→      }
   422→    >
   423→      <Box paddingBlockEnd="1600">
   424→      <Layout>
   425→        {isFreePlan && (
   426→          <Layout.Section>
   427→            <Banner
   428→              tone="info"
   429→              title="Delivery rules require a paid plan"
   430→              action={{
   431→                content: "View pricing plans",
   432→                onAction: () => navigate("/app/pricing"),
   433→              }}
   434→            >
   435→              <Text as="p">
   436→                Upgrade to the Starter plan or higher to create delivery rules
   437→                with custom fees, schedules, and zone conditions.
   438→              </Text>
   439→            </Banner>
   440→          </Layout.Section>
   441→        )}
   442→        {hasFiniteLimit && (
   443→          <Layout.Section>
   444→            <InlineStack align="end">
   445→              <Badge
   446→                tone={
   447→                  (rules as Rule[]).length >= limits.maxDeliveryRules
   448→                    ? "warning"
   449→                    : undefined
   450→                }
   451→              >
   452→                {`${(rules as Rule[]).length}/${limits.maxDeliveryRules} rules used`}
   453→              </Badge>
   454→            </InlineStack>
   455→          </Layout.Section>
   456→        )}
   457→        <Layout.Section>
   458→          <Card padding="0">
   459→            {(rules as Rule[]).length === 0 ? (
   460→              <EmptyState
   461→                heading="No delivery rules yet"
   462→                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
   463→                action={
   464→                  isFreePlan
   465→                    ? {
   466→                        content: "Upgrade to create rules",
   467→                        onAction: () => navigate("/app/pricing"),
   468→                      }
   469→                    : {
   470→                        content: "Create your first rule",
   471→                        onAction: openCreate,
   472→                      }
   473→                }
   474→              >
   475→                <Text as="p">
   476→                  Delivery rules let you set fees, minimum order amounts,
   477→                  estimated delivery times, and delivery schedules for different
   478→                  zones. Rules are evaluated by priority order.
   479→                </Text>
   480→              </EmptyState>
   481→            ) : (
   482→              <IndexTable
   483→                resourceName={{ singular: "rule", plural: "rules" }}
   484→                itemCount={(rules as Rule[]).length}
   485→                selectedItemsCount={allResourcesSelected ? "All" : selectedResources.length}
   486→                onSelectionChange={handleSelectionChange}
   487→                headings={[
   488→                  { title: "Rule Name" },
   489→                  { title: "Zone" },
   490→                  { title: "Delivery Fee" },
   491→                  { title: "Min. Order" },
   492→                  { title: "ETA" },
   493→                  { title: "Days" },
   494→                  { title: "Actions" },
   495→                ]}
   496→                promotedBulkActions={[
   497→                  { content: "Activate", onAction: () => handleBulkToggle(true) },
   498→                  { content: "Deactivate", onAction: () => handleBulkToggle(false) },
   499→                ]}
   500→                bulkActions={[
   501→                  { content: "Delete selected", onAction: handleBulkDelete },
   502→                ]}
   503→              >
   504→                {(rules as Rule[]).map((rule, index) => (
   505→                  <IndexTable.Row
   506→                    id={rule.id}
   507→                    key={rule.id}
   508→                    selected={selectedResources.includes(rule.id)}
   509→                    position={index}
   510→                  >
   511→                    <IndexTable.Cell>
   512→                      <InlineStack gap="200" blockAlign="center">
   513→                        <Text as="span" fontWeight="bold">{rule.name}</Text>
   514→                        <Badge tone={rule.isActive ? "success" : undefined}>
   515→                          {rule.isActive ? "Active" : "Inactive"}
   516→                        </Badge>
   517→                      </InlineStack>
   518→                    </IndexTable.Cell>
   519→                    <IndexTable.Cell>{rule.zone || "All"}</IndexTable.Cell>
   520→                    <IndexTable.Cell>
   521→                      {rule.deliveryFee != null ? `$${rule.deliveryFee.toFixed(2)}` : "Free"}
   522→                    </IndexTable.Cell>
   523→                    <IndexTable.Cell>
   524→                      {rule.minOrderAmount != null ? `$${rule.minOrderAmount.toFixed(2)}` : "—"}
   525→                    </IndexTable.Cell>
   526→                    <IndexTable.Cell>{rule.estimatedDays || "—"}</IndexTable.Cell>
   527→                    <IndexTable.Cell>{rule.daysOfWeek || "All days"}</IndexTable.Cell>
   528→                    <IndexTable.Cell>
   529→                      <InlineStack gap="200">
   530→                        <Tooltip content={rule.isActive ? "Click to deactivate" : "Click to activate"}>
   531→                          <Button
   532→                            size="slim"
   533→                            variant="tertiary"
   534→                            tone={rule.isActive ? "success" : undefined}
   535→                            onClick={() => handleToggle(rule.id, rule.isActive)}
   536→                            icon={rule.isActive ? ViewIcon : HideIcon}
   537→                            accessibilityLabel={rule.isActive ? "Deactivate rule" : "Activate rule"}
   538→                          />
   539→                        </Tooltip>
   540→                        <Tooltip content="Edit rule">
   541→                          <Button
   542→                            size="slim"
   543→                            variant="tertiary"
   544→                            onClick={() => openEdit(rule)}
   545→                            icon={EditIcon}
   546→                            accessibilityLabel="Edit"
   547→                          />
   548→                        </Tooltip>
   549→                        <Tooltip content="Delete rule">
   550→                          <Button
   551→                            size="slim"
   552→                            variant="tertiary"
   553→                            tone="critical"
   554→                            onClick={() => handleDelete(rule.id)}
   555→                            icon={DeleteIcon}
   556→                            accessibilityLabel="Delete"
   557→                          />
   558→                        </Tooltip>
   559→                      </InlineStack>
   560→                    </IndexTable.Cell>
   561→                  </IndexTable.Row>
   562→                ))}
   563→              </IndexTable>
   564→            )}
   565→          </Card>
   566→        </Layout.Section>
   567→      </Layout>
   568→      </Box>
   569→
   570→      {/* Create / Edit Modal */}
   571→      <Modal
   572→        open={modalOpen}
   573→        onClose={() => {
   574→          setModalOpen(false);
   575→          resetForm();
   576→        }}
   577→        title={editingRule ? "Edit Delivery Rule" : "Create Delivery Rule"}
   578→        primaryAction={{
   579→          content: editingRule ? "Save Changes" : "Create Rule",
   580→          onAction: handleSave,
   581→        }}
   582→        secondaryActions={[
   583→          {
   584→            content: "Cancel",
   585→            onAction: () => {
   586→              setModalOpen(false);
   587→              resetForm();
   588→            },
   589→          },
   590→        ]}
   591→      >
   592→        <Modal.Section>
   593→          <BlockStack gap="400">
   594→            {actionError && <Banner tone="critical">{actionError}</Banner>}
   595→
   596→            <TextField
   597→              label="Rule Name"
   598→              value={name}
   599→              onChange={setName}
   600→              placeholder="e.g. Manhattan Standard Delivery"
   601→              autoComplete="off"
