    51→export const loader = async ({ request }: LoaderFunctionArgs) => {
    52→  const { session } = await authenticate.admin(request);
    53→  const shop = session.shop;
    54→
    55→  const [entries, subscription] = await Promise.all([
    56→    db.waitlistEntry.findMany({
    57→      where: { shop },
    58→      orderBy: { createdAt: "desc" },
    59→    }),
    60→    getShopSubscription(shop),
    61→  ]);
    62→
    63→  const stats = {
    64→    total: entries.length,
    65→    waiting: entries.filter((e) => e.status === "waiting").length,
    66→    accepted: entries.filter((e) => e.status === "accepted").length,
    67→    rejected: entries.filter((e) => e.status === "rejected").length,
    68→    notified: entries.filter((e) => e.status === "notified").length,
    69→    converted: entries.filter((e) => e.status === "converted").length,
    70→    uniqueZips: [...new Set(entries.map((e) => e.zipCode))].length,
    71→  };
    72→
    73→  return { entries, stats, subscription };
    74→};
    75→
    76→export const action = async ({ request }: ActionFunctionArgs) => {
    77→  const { session } = await authenticate.admin(request);
    78→  const shop = session.shop;
    79→  const formData = await request.formData();
    80→  const intent = formData.get("intent");
    81→
    82→  // Fetch email sender settings once for any action that may send emails
    83→  const shopSettings = await db.shopSettings.findUnique({ where: { shop } });
    84→  const emailOpts: EmailOptions = {
    85→    senderName: shopSettings?.emailSenderName,
    86→    shopDisplayName: shopSettings?.shopName,
    87→    replyTo: shopSettings?.emailReplyTo,
    88→  };
    89→
    90→  if (intent === "add") {
    91→    const email = String(formData.get("email") || "").trim().toLowerCase();
    92→    const zipCode = String(formData.get("zipCode") || "")
    93→      .trim()
    94→      .toUpperCase();
    95→    const note = String(formData.get("note") || "").trim() || null;
    96→
    97→    if (!email || !zipCode) return { error: "Email and zip code are required." };
    98→
    99→    const subscription = await getShopSubscription(shop);
   100→    const limits = PLAN_LIMITS[subscription.planTier];
   101→
   102→    if (limits.maxWaitlist === 0) {
   103→      return { error: "Your current plan does not include waitlist access. Upgrade to Starter or higher." };
   104→    }
   105→
   106→    if (limits.maxWaitlist < UNLIMITED) {
   107→      const currentCount = await db.waitlistEntry.count({ where: { shop } });
   108→      if (currentCount >= limits.maxWaitlist) {
   109→        return { error: `You have reached the ${limits.maxWaitlist}-entry waitlist limit on your ${limits.label} plan. Upgrade to Pro for unlimited entries.` };
   110→      }
   111→    }
   112→
   113→    try {
   114→      await db.waitlistEntry.create({
   115→        data: { shop, email, zipCode, note },
   116→      });
   117→      return { success: true, action: "added" };
   118→    } catch {
   119→      return { error: "This email is already on the waitlist for this zip code." };
   120→    }
   121→  }
   122→
   123→  if (intent === "delete") {
   124→    const id = String(formData.get("id"));
   125→    try {
   126→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
   127→      if (!existing) return { error: "Entry not found." };
   128→      await db.waitlistEntry.delete({ where: { id } });
   129→      return { success: true, action: "deleted" };
   130→    } catch {
   131→      return { error: "Failed to delete entry." };
   132→    }
   133→  }
   134→
   135→  if (intent === "update-status") {
   136→    const id = String(formData.get("id"));
   137→    const status = String(formData.get("status"));
   138→    try {
   139→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
   140→      if (!existing) return { error: "Entry not found." };
   141→      await db.waitlistEntry.update({ where: { id }, data: { status } });
   142→      return { success: true, action: "updated" };
   143→    } catch {
   144→      return { error: "Failed to update entry status." };
   145→    }
   146→  }
   147→
   148→  if (intent === "notify-zip") {
   149→    const zipCode = String(formData.get("zipCode") || "").trim().toUpperCase();
   150→    if (!zipCode) return { error: "No ZIP code specified." };
   151→
   152→    const notifyZipSub = await getShopSubscription(shop);
   153→    if (PLAN_LIMITS[notifyZipSub.planTier].maxWaitlist < UNLIMITED) {
   154→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
   155→    }
   156→
   157→    const notifyZipEntries = await db.waitlistEntry.findMany({
   158→      where: { shop, zipCode, status: "waiting" },
   159→      select: { id: true, email: true },
   160→    });
   161→
   162→    if (notifyZipEntries.length === 0) {
   163→      return { action: "notify-zip", zipCode, emails: [] as string[], count: 0 };
   164→    }
   165→
   166→    await db.waitlistEntry.updateMany({
   167→      where: { shop, zipCode, status: "waiting" },
   168→      data: { status: "notified" },
   169→    });
   170→
   171→    const emails = notifyZipEntries.map((e) => e.email);
   172→    const shopUrl = `https://${shop}`;
   173→    const emailResults = await Promise.allSettled(
   174→      emails.map((email) =>
   175→        sendZipAvailableNotification(email, zipCode, shop, shopUrl, emailOpts),
   176→      ),
   177→    );
   178→    const emailsSent = emailResults.filter(
   179→      (r) => r.status === "fulfilled" && r.value,
   180→    ).length;
   181→
   182→    return { action: "notify-zip", zipCode, emails, count: emails.length, emailsSent };
   183→  }
   184→
   185→  if (intent === "notify-selected-zips") {
   186→    const zipCodesRaw = String(formData.get("zipCodes") || "");
   187→    const zipCodes = zipCodesRaw.split(",").map(z => z.trim().toUpperCase()).filter(Boolean);
   188→    if (zipCodes.length === 0) return { error: "No ZIP codes selected." };
   189→
   190→    const notifyZipsSub = await getShopSubscription(shop);
   191→    if (PLAN_LIMITS[notifyZipsSub.planTier].maxWaitlist < UNLIMITED) {
   192→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
   193→    }
   194→
   195→    const waitingEntries = await db.waitlistEntry.findMany({
   196→      where: { shop, status: "waiting", zipCode: { in: zipCodes } },
   197→      select: { id: true, email: true, zipCode: true },
   198→    });
   199→
   200→    if (waitingEntries.length === 0) {
   201→      return { action: "notify-selected-zips", emails: [] as string[], count: 0, zipBreakdown: [] as { zipCode: string; count: number }[] };
   202→    }
   203→
   204→    await db.waitlistEntry.updateMany({
   205→      where: { shop, status: "waiting", zipCode: { in: zipCodes } },
   206→      data: { status: "notified" },
   207→    });
   208→
   209→    const zipMap = new Map<string, number>();
   210→    for (const entry of waitingEntries) {
   211→      zipMap.set(entry.zipCode, (zipMap.get(entry.zipCode) ?? 0) + 1);
   212→    }
   213→    const zipBreakdown = Array.from(zipMap.entries()).map(([zipCode, count]) => ({ zipCode, count }));
   214→    const emails = waitingEntries.map(e => e.email);
   215→
   216→    const shopUrl = `https://${shop}`;
   217→    const emailResults = await Promise.allSettled(
   218→      waitingEntries.map((e) =>
   219→        sendZipAvailableNotification(e.email, e.zipCode, shop, shopUrl, emailOpts),
   220→      ),
   221→    );
   222→    const emailsSent = emailResults.filter(
   223→      (r) => r.status === "fulfilled" && r.value,
   224→    ).length;
   225→
   226→    return { action: "notify-selected-zips", emails, count: emails.length, zipBreakdown, emailsSent };
   227→  }
   228→
   229→  if (intent === "bulk-action") {
   230→    const idsRaw = String(formData.get("ids") || "");
   231→    const ids = idsRaw.split(",").filter(Boolean);
   232→    const bulkType = String(formData.get("bulkType") || "");
   233→
   234→    if (ids.length === 0) return { error: "No entries selected." };
   235→
   236→    const bulkSub = await getShopSubscription(shop);
   237→
   238→    if (bulkType === "notify") {
   239→      if (PLAN_LIMITS[bulkSub.planTier].maxWaitlist < UNLIMITED) {
   240→        return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
   241→      }
   242→      const entriesToNotify = await db.waitlistEntry.findMany({
   243→        where: { id: { in: ids }, shop, status: "waiting" },
   244→        select: { id: true, email: true, zipCode: true },
   245→      });
   246→      if (entriesToNotify.length === 0) {
   247→        return { action: "bulk-action-notify", emails: [] as string[], count: 0, zipBreakdown: [] as { zipCode: string; count: number }[] };
   248→      }
   249→      await db.waitlistEntry.updateMany({
   250→        where: { id: { in: ids }, shop, status: "waiting" },
   251→        data: { status: "notified" },
   252→      });
   253→      const zipMap = new Map<string, number>();
   254→      for (const e of entriesToNotify) {
   255→        zipMap.set(e.zipCode, (zipMap.get(e.zipCode) ?? 0) + 1);
   256→      }
   257→      const zipBreakdown = Array.from(zipMap.entries()).map(([z, c]) => ({ zipCode: z, count: c }));
   258→
   259→      const shopUrl = `https://${shop}`;
   260→      const emailResults = await Promise.allSettled(
   261→        entriesToNotify.map((e) =>
   262→          sendZipAvailableNotification(e.email, e.zipCode, shop, shopUrl, emailOpts),
   263→        ),
   264→      );
   265→      const emailsSent = emailResults.filter(
   266→        (r) => r.status === "fulfilled" && r.value,
   267→      ).length;
   268→
   269→      return { action: "bulk-action-notify", emails: entriesToNotify.map(e => e.email), count: entriesToNotify.length, zipBreakdown, emailsSent };
   270→    }
   271→
   272→    if (bulkType === "accept") {
   273→      const entriesToAccept = await db.waitlistEntry.findMany({
   274→        where: { id: { in: ids }, shop },
   275→        select: { id: true, email: true, name: true, zipCode: true },
   276→      });
   277→      for (const entry of entriesToAccept) {
   278→        await db.zipCode.upsert({
   279→          where: { shop_zipCode: { shop, zipCode: entry.zipCode } },
   280→          create: { shop, zipCode: entry.zipCode, type: "allowed", isActive: true, label: `Requested by ${entry.name || entry.email}` },
   281→          update: { type: "allowed", isActive: true },
   282→        });
   283→      }
   284→      await db.waitlistEntry.updateMany({
   285→        where: { id: { in: ids }, shop },
   286→        data: { status: "accepted" },
   287→      });
   288→      return { success: true, action: "bulk-accepted", count: entriesToAccept.length };
   289→    }
   290→
   291→    if (bulkType === "delete") {
   292→      const result = await db.waitlistEntry.deleteMany({
   293→        where: { id: { in: ids }, shop },
   294→      });
   295→      return { success: true, action: "bulk-deleted", count: result.count };
   296→    }
   297→
   298→    return { error: "Unknown bulk action type." };
   299→  }
   300→
   301→  if (intent === "delete-all-notified") {
   302→    const deleted = await db.waitlistEntry.deleteMany({
   303→      where: { shop, status: "notified" },
   304→    });
   305→    return { success: true, action: "deleted-notified", count: deleted.count };
   306→  }
   307→
   308→  if (intent === "accept") {
   309→    const id = String(formData.get("id"));
   310→    const entry = await db.waitlistEntry.findUnique({ where: { id } });
   311→    if (!entry || entry.shop !== shop) {
   312→      return { error: "Entry not found." };
   313→    }
   314→
   315→    await db.zipCode.upsert({
   316→      where: { shop_zipCode: { shop, zipCode: entry.zipCode } },
   317→      create: {
   318→        shop,
   319→        zipCode: entry.zipCode,
   320→        type: "allowed",
   321→        isActive: true,
   322→        label: `Requested by ${entry.name || entry.email}`,
   323→      },
   324→      update: {
   325→        type: "allowed",
   326→        isActive: true,
   327→      },
   328→    });
   329→
   330→    await db.waitlistEntry.update({
   331→      where: { id },
   332→      data: { status: "accepted" },
   333→    });
   334→
   335→    return { success: true, action: "accepted", zipCode: entry.zipCode };
   336→  }
   337→
   338→  return null;
   339→};
