   185→// ---------------------------------------------------------------------------
   186→// Loader
   187→// ---------------------------------------------------------------------------
   188→
   189→export const loader = async ({ request }: LoaderFunctionArgs) => {
   190→  const { session } = await authenticate.admin(request);
   191→  const shop = session.shop;
   192→
   193→  const [features, myVotes] = await Promise.all([
   194→    db.featureRequest.findMany({
   195→      orderBy: { votesCount: "desc" },
   196→      take: 500,
   197→    }),
   198→    db.featureVote.findMany({
   199→      where: { shop },
   200→      select: { featureRequestId: true },
   201→    }),
   202→  ]);
   203→
   204→  const votedIds = myVotes.map((v) => v.featureRequestId);
   205→
   206→  const stats = {
   207→    total: features.length,
   208→    under_review: features.filter((f) => f.status === "under_review").length,
   209→    planned: features.filter((f) => f.status === "planned").length,
   210→    in_progress: features.filter((f) => f.status === "in_progress").length,
   211→    done: features.filter(
   212→      (f) => f.status === "done" || f.status === "shipped",
   213→    ).length,
   214→  };
   215→
   216→  const isAdmin = shop === ADMIN_SHOP;
   217→
   218→  return { features, votedIds, shop, stats, isAdmin };
   219→};
