   221→// ---------------------------------------------------------------------------
   222→// Action
   223→// ---------------------------------------------------------------------------
   224→
   225→export const action = async ({
   226→  request,
   227→}: ActionFunctionArgs): Promise<ActionResult> => {
   228→  const { session } = await authenticate.admin(request);
   229→  const shop = session.shop;
   230→  const isAdmin = shop === ADMIN_SHOP;
   231→  const formData = await request.formData();
   232→  const intent = String(formData.get("intent") ?? "");
   233→
   234→  try {
   235→    switch (intent) {
   236→      case "submit": {
   237→        const title = String(formData.get("title") ?? "").trim();
   238→        const description = String(formData.get("description") ?? "").trim();
   239→        const rawCategory = String(formData.get("category") ?? "General").trim();
   240→        const category = VALID_CATEGORIES.has(rawCategory) ? rawCategory : "General";
   241→
   242→        if (!title || !description) {
   243→          return { error: "Title and description are required." };
   244→        }
   245→        if (title.length > 150) {
   246→          return { error: "Title must be 150 characters or fewer." };
   247→        }
   248→        if (description.length > MAX_DESCRIPTION_LENGTH) {
   249→          return { error: `Description must be ${MAX_DESCRIPTION_LENGTH} characters or fewer.` };
   250→        }
   251→
   252→        // Per-shop submission limit
   253→        const existingCount = await db.featureRequest.count({ where: { shop } });
   254→        if (existingCount >= MAX_REQUESTS_PER_SHOP) {
   255→          return { error: `You can submit up to ${MAX_REQUESTS_PER_SHOP} feature requests. Delete an existing one to submit a new one.` };
   256→        }
   257→
   258→        await db.featureRequest.create({
   259→          data: { title, description, category, shop },
   260→        });
   261→
   262→        return { success: true, intent: "submit" };
   263→      }
   264→
   265→      case "vote": {
   266→        const featureId = String(formData.get("featureId") ?? "").trim();
   267→        if (!featureId) return { error: "Feature ID is required." };
   268→
   269→        const feature = await db.featureRequest.findUnique({
   270→          where: { id: featureId },
   271→        });
   272→        if (!feature) return { error: "Feature request not found." };
   273→
   274→        const existing = await db.featureVote.findUnique({
   275→          where: {
   276→            featureRequestId_shop: { featureRequestId: featureId, shop },
   277→          },
   278→        });
   279→
   280→        let voted: boolean;
   281→
   282→        if (existing) {
   283→          await db.featureVote.delete({ where: { id: existing.id } });
   284→          // Atomic decrement
   285→          const updated = await db.featureRequest.update({
   286→            where: { id: featureId },
   287→            data: { votesCount: { decrement: 1 } },
   288→          });
   289→          // Ensure count doesn't go below 0
   290→          if (updated.votesCount < 0) {
   291→            await db.featureRequest.update({
   292→              where: { id: featureId },
   293→              data: { votesCount: 0 },
   294→            });
   295→          }
   296→          voted = false;
   297→          const finalCount = Math.max(0, updated.votesCount);
   298→          return { success: true, intent: "vote", featureId, newCount: finalCount, voted };
   299→        } else {
   300→          await db.featureVote.create({
   301→            data: { featureRequestId: featureId, shop },
   302→          });
   303→          // Atomic increment
   304→          const updated = await db.featureRequest.update({
   305→            where: { id: featureId },
   306→            data: { votesCount: { increment: 1 } },
   307→          });
   308→          voted = true;
   309→          return { success: true, intent: "vote", featureId, newCount: updated.votesCount, voted };
   310→        }
   311→      }
   312→
   313→      case "delete": {
   314→        const deleteId = String(formData.get("id") ?? "").trim();
   315→        if (!deleteId) return { error: "Feature ID is required." };
   316→
   317→        const toDelete = await db.featureRequest.findUnique({
   318→          where: { id: deleteId },
   319→        });
   320→        if (!toDelete) return { error: "Feature request not found." };
   321→
   322→        // Admin can delete any, regular users only their own
   323→        if (!isAdmin && toDelete.shop !== shop) {
   324→          return { error: "You can only delete your own feature requests." };
   325→        }
   326→
   327→        await db.featureRequest.delete({ where: { id: deleteId } });
   328→        return { success: true, intent: "delete" };
   329→      }
   330→
   331→      case "edit": {
   332→        const editId = String(formData.get("id") ?? "").trim();
   333→        const editTitle = String(formData.get("title") ?? "").trim();
   334→        const editDescription = String(formData.get("description") ?? "").trim();
   335→        const rawEditCategory = String(formData.get("category") ?? "General").trim();
   336→        const editCategory = VALID_CATEGORIES.has(rawEditCategory) ? rawEditCategory : "General";
   337→
   338→        if (!editId) return { error: "Feature ID is required." };
   339→        if (!editTitle || !editDescription) {
   340→          return { error: "Title and description are required." };
   341→        }
   342→        if (editTitle.length > 150) {
   343→          return { error: "Title must be 150 characters or fewer." };
   344→        }
   345→        if (editDescription.length > MAX_DESCRIPTION_LENGTH) {
   346→          return { error: `Description must be ${MAX_DESCRIPTION_LENGTH} characters or fewer.` };
   347→        }
   348→
   349→        const toEdit = await db.featureRequest.findUnique({ where: { id: editId } });
   350→        if (!toEdit) return { error: "Feature request not found." };
   351→
   352→        if (!isAdmin && toEdit.shop !== shop) {
   353→          return { error: "You can only edit your own feature requests." };
   354→        }
   355→
   356→        const editData: { title: string; description: string; category: string; status?: string } = {
   357→          title: editTitle,
   358→          description: editDescription,
   359→          category: editCategory,
   360→        };
   361→
   362→        // Admin can also change status via the edit form
   363→        const editStatus = String(formData.get("status") ?? "").trim();
   364→        if (isAdmin && editStatus && VALID_STATUSES.has(editStatus)) {
   365→          editData.status = editStatus;
   366→        }
   367→
   368→        await db.featureRequest.update({
   369→          where: { id: editId },
   370→          data: editData,
   371→        });
   372→
   373→        return { success: true, intent: "edit" };
   374→      }
   375→
   376→      case "update-status": {
   377→        if (!isAdmin) {
   378→          return { error: "Only the app admin can change request statuses." };
   379→        }
   380→
   381→        const statusId = String(formData.get("id") ?? "").trim();
   382→        const newStatus = String(formData.get("status") ?? "").trim();
   383→
   384→        if (!statusId) return { error: "Feature ID is required." };
   385→        if (!VALID_STATUSES.has(newStatus)) {
   386→          return { error: "Invalid status value." };
   387→        }
   388→
   389→        const toUpdate = await db.featureRequest.findUnique({
   390→          where: { id: statusId },
   391→        });
   392→        if (!toUpdate) return { error: "Feature request not found." };
   393→
   394→        await db.featureRequest.update({
   395→          where: { id: statusId },
   396→          data: { status: newStatus },
   397→        });
   398→
   399→        return { success: true, intent: "update-status" };
   400→      }
   401→
   402→      default:
   403→        return { error: "Unknown action." };
   404→    }
   405→  } catch (err) {
   406→    const message =
   407→      err instanceof Error ? err.message : "An unexpected error occurred.";
   408→    return { error: message };
   409→  }
   410→};
