   412→// ---------------------------------------------------------------------------
   413→// Component
   414→// ---------------------------------------------------------------------------
   415→
   416→export default function FeatureRequestsPage() {
   417→  const {
   418→    features: rawFeatures,
   419→    votedIds: initialVotedIds,
   420→    shop,
   421→    stats,
   422→    isAdmin,
   423→  } = useLoaderData<typeof loader>();
   424→
   425→  // Separate fetchers for independent actions
   426→  const voteFetcher = useFetcher<typeof action>();
   427→  const deleteFetcher = useFetcher<typeof action>();
   428→  const submitFetcher = useFetcher<typeof action>();
   429→
   430→  const editFetcher = useFetcher<typeof action>();
   431→
   432→  const shopify = useAppBridge();
   433→  const navigate = useNavigate();
   434→
   435→  // ------------------------------------------------------------------
   436→  // Local state — optimistic votes
   437→  // ------------------------------------------------------------------
   438→  const [optimisticVotes, setOptimisticVotes] = useState<
   439→    Map<string, { count: number; voted: boolean }>
   440→  >(() => new Map());
   441→  const [votedIds, setVotedIds] = useState<Set<string>>(
   442→    () => new Set(initialVotedIds),
   443→  );
   444→
   445→  // Per-card loading indicators
   446→  const [pendingVoteId, setPendingVoteId] = useState<string | null>(null);
   447→  const [pendingDeleteId, setPendingDeleteId] = useState<string | null>(null);
   448→
   449→  // ------------------------------------------------------------------
   450→  // UI state
   451→  // ------------------------------------------------------------------
   452→  const [selectedTab, setSelectedTab] = useState(0);
   453→  const [sortValue, setSortValue] = useState("votes");
   454→  const [currentPage, setCurrentPage] = useState(1);
   455→  const [modalOpen, setModalOpen] = useState(false);
   456→  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
   457→  const [modalError, setModalError] = useState<string | null>(null);
   458→  const [searchQuery, setSearchQuery] = useState("");
   459→
   460→  // Form state
   461→  const [newTitle, setNewTitle] = useState("");
   462→  const [newDescription, setNewDescription] = useState("");
   463→  const [newCategory, setNewCategory] = useState("General");
   464→
   465→  // Delete confirmation state
   466→  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
   467→
   468→  // Edit modal state
   469→  const [editModalOpen, setEditModalOpen] = useState(false);
   470→  const [editId, setEditId] = useState("");
   471→  const [editTitle, setEditTitle] = useState("");
   472→  const [editDescription, setEditDescription] = useState("");
   473→  const [editCategory, setEditCategory] = useState("General");
   474→  const [editStatus, setEditStatus] = useState("under_review");
   475→  const [editModalError, setEditModalError] = useState<string | null>(null);
   476→
   477→  // ------------------------------------------------------------------
   478→  // Resolve optimistic state into features list
   479→  // ------------------------------------------------------------------
   480→  const features = useMemo<FeatureRequestRecord[]>(() => {
   481→    return (rawFeatures as FeatureRequestRecord[]).map((f) => {
   482→      const opt = optimisticVotes.get(f.id);
   483→      if (opt) return { ...f, votesCount: opt.count };
   484→      return f;
   485→    });
   486→  }, [rawFeatures, optimisticVotes]);
   487→
   488→  // ------------------------------------------------------------------
   489→  // Handle vote fetcher responses
   490→  // ------------------------------------------------------------------
   491→  useEffect(() => {
   492→    if (voteFetcher.state !== "idle" || !voteFetcher.data) return;
   493→    const data = voteFetcher.data;
   494→
   495→    if ("error" in data) {
   496→      shopify.toast.show(data.error, { isError: true });
   497→      setPendingVoteId(null);
   498→      return;
   499→    }
   500→
   501→    if ("success" in data && data.success && data.intent === "vote") {
   502→      const voteData = data as VoteResult;
   503→      setOptimisticVotes((prev) => {
   504→        const next = new Map(prev);
   505→        next.set(voteData.featureId, {
   506→          count: voteData.newCount,
   507→          voted: voteData.voted,
   508→        });
   509→        return next;
   510→      });
   511→      setVotedIds((prev) => {
   512→        const next = new Set(prev);
   513→        if (voteData.voted) next.add(voteData.featureId);
   514→        else next.delete(voteData.featureId);
   515→        return next;
   516→      });
   517→      setPendingVoteId(null);
   518→    }
   519→  }, [voteFetcher.state, voteFetcher.data, shopify]);
   520→
   521→  // ------------------------------------------------------------------
   522→  // Handle delete fetcher responses
   523→  // ------------------------------------------------------------------
   524→  useEffect(() => {
   525→    if (deleteFetcher.state !== "idle" || !deleteFetcher.data) return;
   526→    const data = deleteFetcher.data;
   527→
   528→    if ("error" in data) {
   529→      shopify.toast.show(data.error, { isError: true });
   530→      setPendingDeleteId(null);
   531→      return;
   532→    }
   533→
   534→    if ("success" in data && data.success && data.intent === "delete") {
   535→      shopify.toast.show("Feature request deleted.");
   536→      setPendingDeleteId(null);
   537→      setConfirmDeleteId(null);
   538→    }
   539→  }, [deleteFetcher.state, deleteFetcher.data, shopify]);
   540→
   541→  // ------------------------------------------------------------------
   542→  // Handle submit fetcher responses
   543→  // ------------------------------------------------------------------
   544→  useEffect(() => {
   545→    if (submitFetcher.state !== "idle" || !submitFetcher.data) return;
   546→    const data = submitFetcher.data;
   547→
   548→    if ("error" in data) {
   549→      setModalError(data.error);
   550→      return;
   551→    }
   552→
   553→    if ("success" in data && data.success && data.intent === "submit") {
   554→      shopify.toast.show("Feature request submitted! Thank you.");
   555→      setModalOpen(false);
   556→      setNewTitle("");
   557→      setNewDescription("");
   558→      setNewCategory("General");
   559→      setModalError(null);
   560→      // Bring the new request into view: switch to All tab, sort by Newest, page 1
   561→      setSelectedTab(0);
   562→      setSortValue("newest");
   563→      setCurrentPage(1);
   564→    }
   565→  }, [submitFetcher.state, submitFetcher.data, shopify]);
   566→
   567→  // ------------------------------------------------------------------
   568→  // Handle edit fetcher responses
   569→  // ------------------------------------------------------------------
   570→  useEffect(() => {
   571→    if (editFetcher.state !== "idle" || !editFetcher.data) return;
   572→    const data = editFetcher.data;
   573→
   574→    if ("error" in data) {
   575→      setEditModalError(data.error);
   576→      return;
   577→    }
   578→
   579→    if ("success" in data && data.success && data.intent === "edit") {
   580→      shopify.toast.show("Feature request updated.");
   581→      setEditModalOpen(false);
   582→      setEditId("");
   583→      setEditTitle("");
   584→      setEditDescription("");
   585→      setEditCategory("General");
   586→      setEditModalError(null);
   587→    }
   588→  }, [editFetcher.state, editFetcher.data, shopify]);
   589→
   590→  // ------------------------------------------------------------------
   591→  // Filter + sort
   592→  // ------------------------------------------------------------------
   593→  const tabFilter: TabFilter = TAB_FILTERS[selectedTab] ?? "all";
   594→
   595→  const filteredFeatures = useMemo(() => {
   596→    let list = features;
   597→
   598→    if (tabFilter !== "all") {
   599→      if (tabFilter === "done") {
   600→        list = list.filter(
   601→          (f) => f.status === "done" || f.status === "shipped",
   602→        );
   603→      } else {
   604→        list = list.filter((f) => f.status === tabFilter);
   605→      }
   606→    }
   607→
   608→    // Apply search filter (client-side, case-insensitive)
   609→    if (searchQuery.trim()) {
   610→      const q = searchQuery.trim().toLowerCase();
   611→      list = list.filter(
   612→        (f) =>
   613→          f.title.toLowerCase().includes(q) ||
   614→          f.description.toLowerCase().includes(q),
   615→      );
   616→    }
   617→
   618→    return [...list].sort((a, b) => {
   619→      if (sortValue === "votes") return b.votesCount - a.votesCount;
   620→      if (sortValue === "newest")
   621→        return (
   622→          new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
   623→        );
   624→      if (sortValue === "oldest")
   625→        return (
   626→          new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
   627→        );
   628→      return 0;
   629→    });
   630→  }, [features, tabFilter, sortValue, searchQuery]);
   631→
   632→  const totalPages = Math.max(
   633→    1,
   634→    Math.ceil(filteredFeatures.length / PAGE_SIZE),
